-- Discovers service destinations in bounded slices and owns the guide’s training lookup.

local Constants = APR.NavigationConstants.Services

local Services = APR.Services
local Shared = APR.Services._helpers
local Character = Shared.Character
local Message = Shared.Message
local Number = Shared.Number
local Position = Shared.Position
local Profile = Shared.Profile

-- Training is an objective of the current guide, not a service detour. Keep its
-- result separate so arriving never dismisses the learning instruction.
function Services:IsTrainingCurrent(owner)
    return APR.settings
        and APR.settings.profile
        and APR.settings.profile.enableAddon
        and APR:IsStepContextCurrent(owner.context)
        and APR:GetCurrentStep() == owner.step
        and not owner.step.Coord
        and not owner.step.Coords
        and (not APR.AreConditionalFiltersMet or APR:AreConditionalFiltersMet(owner.step))
end--[[APR_DIAG]]; Services.IsTrainingCurrent = APRTrace("APR-Core/features/navigation/services/ServiceSearch.lua:20:Services:IsTrainingCurrent#1", Services.IsTrainingCurrent)--[[/APR_DIAG]]

function Services:CancelTraining()
    if self.request and self.request.training then self:CancelSearch() end
    self.training = nil
end--[[APR_DIAG]]; Services.CancelTraining = APRTrace("APR-Core/features/navigation/services/ServiceSearch.lua:31:Services:CancelTraining#2", Services.CancelTraining)--[[/APR_DIAG]]

function Services:GetTrainingDestination(step)
    if step.Coord or step.Coords or not (step.LearnProfession or step.LearnSkill) then
        self:CancelTraining()
        return
    end
    local rule = type(step.LearnSkill) == "table" and step.LearnSkill or {}
    local spells = step.LearnProfession and { step.LearnProfession }
        or (rule.spellID and { rule.spellID })
        or rule.spellIDs
    local data = APR.NavigationData
    if not data or not data.GetTrainingServiceQuery then return nil, nil, "pending_data" end
    local query =
        data:GetTrainingServiceQuery(spells and #spells == 1 and spells[1] or nil, step.LearnProfession ~= nil)
    query.npcID = rule.npcID
    if spells and #spells > 1 then query.spellIDs = spells end
    local signature = tostring(query.service) .. ":" .. tostring(query.skill) .. ":" .. tostring(query.npcID)
    for _, id in ipairs(spells or {}) do
        signature = signature .. ":" .. tostring(id)
    end
    local owner = self.training
    if
        owner
        and (
            not self:IsTrainingCurrent(owner)
            or owner.signature ~= signature
            or owner.geometry ~= APR.navigationGeometryRevision
            or owner.profile ~= Profile()
            or (owner.record and data:ServiceMatches(owner.record, query, Character()) ~= true)
        )
    then
        self:CancelTraining()
        owner = nil
    end
    if not owner then
        owner = {
            step = step,
            context = APR:CaptureStepContext(),
            signature = signature,
            query = query,
            geometry = APR.navigationGeometryRevision,
            profile = Profile(),
            status = "waiting_data",
        }
        self.training = owner
    end
    if not self:IsTrainingCurrent(owner) then return nil, nil, "pending_data" end
    if owner.target then return owner.target, owner.target.uiMapID end
    if not self.request and owner.status ~= "no_path" then self:Find(query, owner) end
    return nil, nil, owner.status == "no_path" and "service_not_found" or "pending_data"
end--[[APR_DIAG]]; Services.GetTrainingDestination = APRTrace("APR-Core/features/navigation/services/ServiceSearch.lua:36:Services:GetTrainingDestination#3", Services.GetTrainingDestination)--[[/APR_DIAG]]

function Services:Find(query, training, resuming)
    local nav = APR.navigation
    if not training and not resuming and nav and nav.BeginGuidanceMeasurement then
        nav:BeginGuidanceMeasurement("service")
    end
    self:CancelSearch()
    if not APR.settings or not APR.settings.profile.enableAddon then return false end
    local data, start, profile = APR.NavigationData, Position(), Profile()
    if not data or (profile ~= "forever" and profile ~= "retail") then
        if not training then Message("SERVICE_WAITING_DATA") end
        return false
    end
    local character = Character()
    local request = {
        query = query,
        start = start,
        route = APR.ActiveRoute,
        player = APR.PlayerID,
        generation = self.generation,
        character = character,
        training = training,
        money = GetMoney and GetMoney() or 0,
        geometry = APR.navigationGeometryRevision,
        profile = profile,
        taxiRevision = APR.taxiData and APR.taxiData.edgeRevision,
        taxiSnapshot = APR.taxiData and APR.taxiData.GetSnapshotKey and APR.taxiData:GetSnapshotKey(),
    }
    if not start then
        if not training then Message("SERVICE_WAITING_DATA") end
        if training or profile ~= "forever" then return false end
        self.request, request.waitingForOrigin = request, true
        nav:RefreshActivity()
        return true
    end
    local speed, ceiling, speedAt, speedFor, flight
    local terrain = profile == "retail" and data.GetWalkingProvider and data:GetWalkingProvider()
    local coveredRetail = terrain and terrain.HasWalkingCoverage and terrain:HasWalkingCoverage(start)
    if (profile == "forever" or coveredRetail) and nav.GetWalkingSpeedModel then
        speed, ceiling, speedAt, speedFor, flight = nav:GetWalkingSpeedModel(start, nav:GetThreshold())
    else
        speed = nav:GetMovementSpeed(nav:GetThreshold())
        local ground = math.min(nav:GetMovementSpeed(2000), 14)
        if profile == "forever" then ceiling = math.max(speed, ground) end
        speedAt = --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/services/ServiceSearch.lua:128:callback#5", --[[/APR_DIAG]]function(point) return data.GetWalkingSpeed and data:GetWalkingSpeed(point, speed, ground) or speed end--[[APR_DIAG]])--[[/APR_DIAG]]
        speedFor = --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/services/ServiceSearch.lua:129:callback#6", --[[/APR_DIAG]]function(a, b) return math.min(speedAt(a), speedAt(b)) end--[[APR_DIAG]])--[[/APR_DIAG]]
    end
    local activeWalk = profile == "forever"
            and nav.state == "guiding"
            and not nav.worldLoading
            and nav.GetActiveStep
            and nav:GetActiveStep()
        or nil
    request.job = data:CreateServiceSearch({
        query = query,
        character = character,
        start = start,
        nearestByCoordinates = not training,
        batchTerrainWork = profile == "forever" or coveredRetail == true,
        activeWalk = activeWalk,
        adapter = APR.NavigationAdapter,
        flightProvider = APR.taxiData,
        taxiData = APR.taxiData,
        clock = debugprofilestop,
        budget = request.money,
        walkSpeed = speed,
        walkSpeedAt = speedAt,
        walkingSpeedCeiling = ceiling,
        walkSpeedFor = speedFor,
        flight = flight,
    })
    if request.job.status == "unavailable" then
        Message("SERVICE_TAXI_UNAVAILABLE")
        return false
    end
    local coordinateOrigin
    local provider = request.job.walkingProvider
    if not training and activeWalk and start.z == nil and provider and provider.GetServiceOriginHeight then
        -- A coordinate result can publish after another update retires the old walk.
        local height = provider:GetServiceOriginHeight(start, activeWalk)
        if Number(height) then
            coordinateOrigin = {}
            for key, value in pairs(start) do
                coordinateOrigin[key] = value
            end
            coordinateOrigin.z = height
        end
    end
    self.request = request
    local function inputsCurrent()
        local current, observed = Position(), Character()
        if not current then
            if not training and profile == "forever" then
                request.job:Cancel()
                request.job, request.start, request.timer = nil, nil, nil
                request.waitingForOrigin = true
                nav:RefreshActivity()
            else
                self:CancelSearch()
            end
            if not training then Message("SERVICE_WAITING_DATA") end
            return
        end
        if
            current.instanceID ~= start.instanceID
            or current.uiMapID ~= start.uiMapID
            or (current.x - start.x) ^ 2 + (current.y - start.y) ^ 2 > Constants.SEARCH_REPLAN_DISTANCE_YARDS ^ 2
            or (profile == "forever" and (current.floor ~= start.floor or current.accessKey ~= start.accessKey or current.region ~= start.region or (start.z == nil and Number(
                current.z
            )) or (Number(current.z) and request.job.start and Number(request.job.start.z) and math.abs(
                current.z - request.job.start.z
            ) > 5)))
            or observed.faction ~= character.faction
            or observed.class ~= character.class
            or observed.level ~= character.level
            or request.money ~= (GetMoney and GetMoney() or 0)
            or request.geometry ~= APR.navigationGeometryRevision
            or request.profile ~= Profile()
            or request.taxiRevision ~= (APR.taxiData and APR.taxiData.edgeRevision)
            or request.taxiSnapshot
                ~= (APR.taxiData and APR.taxiData.GetSnapshotKey and APR.taxiData:GetSnapshotKey())
        then
