        end
        return true
    end--[[APR_DIAG]]; inputsCurrent = APRTrace("APR-Core/features/navigation/services/ServiceSearch.lua:172:inputsCurrent#7", inputsCurrent)--[[/APR_DIAG]]
    local nextCheck, previousFrame
    local function advance()
        if self.request ~= request or request.generation ~= self.generation or not request.job then return end
        local selecting = not training and request.job.phase == "candidate"
        local sliceStarted = not training
            and (profile == "forever" or selecting)
            and debugprofilestop
            and debugprofilestop()
        local terrainFrame = not selecting
            and profile == "forever"
            and data.BeginTerrainFrame
            and data.HasDeferredTerrainImports
            and data:HasDeferredTerrainImports(start.instanceID)
            and data:BeginTerrainFrame()
        if training and (self.training ~= training or not self:IsTrainingCurrent(training)) then
            self:CancelTraining()
            return
        end
        if
            request.route ~= APR.ActiveRoute
            or request.player ~= APR.PlayerID
            or not APR.settings.profile.enableAddon
            or (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player"))
        then
            self:CancelSearch()
            return
        end
        if request.invalidated then
            self:Find(query, training, true)
            return
        end
        -- A terrain search may span hundreds of slices. Sample its changing
        -- inputs periodically and always validate before publishing a result.
        local now = profile == "forever" and GetTime and GetTime()
        local check = not now or not nextCheck or now >= nextCheck
        if check then
            if not inputsCurrent() then return end
            if now then nextCheck = now + 0.25 end
        end
        -- A manual click may use up to a third of a frame while the player
        -- awaits guidance. Keep existing guidance responsive during a search.
        local foreground = terrainFrame
            and now
            and not training
            and not nav.worldLoading
            and not nav.retainedArrow
            and not nav.recomputeKeepingDirect
            and not nav.recomputeKeepingPath
            and not (APR.ActiveRoute and nav.zoneReady)
            and not (nav.state == "guiding" and nav:GetActiveStep())
        local budget = Constants.SEARCH_SLICE_MS
        if selecting then
            budget = 3
        elseif foreground then
            budget = previousFrame and math.max(1, math.min(5, (now - previousFrame) * 1000 / 3)) or 3
        end
        previousFrame = now
        local deadline = sliceStarted and sliceStarted + budget
        local remaining, status, result = budget, "planning"
        for _ = 1, 64 do
            if terrainFrame and terrainFrame.deferred then break end
            if deadline then
                remaining = deadline - debugprofilestop()
                if remaining <= 0 then break end
            end
            status, result = request.job:Step(debugprofilestop and 4096 or 64, remaining)
            if not deadline or status ~= "planning" or self.request ~= request or request.invalidated then break end
            if selecting and request.job.phase ~= "candidate" then break end
        end
        if self.request ~= request then return end
        if request.invalidated then
            self:Find(query, training, true)
            return
        end
        if status == "planning" then
            request.timer =
                C_Timer.NewTimer((selecting or foreground) and 0 or Constants.SEARCH_SLICE_DELAY_SECONDS, advance)
        elseif status == "cancelled" and (training or profile ~= "forever") then
            self:Find(query, training, true)
        else
            if not inputsCurrent() then return end
            if
                not training
                and profile == "forever"
                and status == "waiting_data"
                and request.job.reason == "origin_surface"
                and request.job.walkingProvider
                and request.job.walkingProvider.IsSameWalkingCell
            then
                request.waitingForOrigin, request.timer = true, nil
                nav:RefreshActivity()
                Message("SERVICE_WAITING_DATA")
                return
            end
            self.request = nil
            if training then
                training.status = status
                if status == "ready" then
                    training.target, training.record = result.target, result.record
                    nav:ForceRefresh("training_destination")
                    nav:RequestUpdate()
                end
            elseif status == "ready" then
                local origin = result.origin or (result.byCoordinates and coordinateOrigin)
                self:Start(result.record, result.target, origin, result.itinerary, start, result.byCoordinates)
            else
                Message(
                    (status == "waiting_data" or status == "cancelled") and "SERVICE_WAITING_DATA"
                        or "SERVICE_NOT_FOUND"
                )
            end
        end
    end--[[APR_DIAG]]; advance = APRTrace("APR-Core/features/navigation/services/ServiceSearch.lua:211:advance#8", advance)--[[/APR_DIAG]]
    if not training then Message("SERVICE_SEARCHING") end
    request.timer = C_Timer.NewTimer(0, advance)
    return true
end--[[APR_DIAG]]; Services.Find = APRTrace("APR-Core/features/navigation/services/ServiceSearch.lua:87:Services:Find#4", Services.Find)--[[/APR_DIAG]]

